using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using CircuitoStudio;
class DiagramEditingTests {
static int n;static void Check(bool b,string s){n++;if(!b)throw new Exception(s);}static void Near(double a,double b,string s){Check(Math.Abs(a-b)<1e-8,s);}static void Reject(Action a,string s){bool fail=false;try{a();}catch(InvalidDataException){fail=true;}catch(InvalidOperationException){fail=true;}Check(fail,s);}
[STAThread]static int Main(){try{var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=10;var a=new Board{Id="A",Name="Raiz Ω",Voltage=400};var b=new Board{Id="B",Name="Distribuição",Voltage=400};var d=new Board{Id="D",Name="Final",Voltage=400};var e=new Board{Id="E",Name="Outra raiz",Voltage=400};p.Boards.AddRange(new[]{a,b,d,e});var load=new Circuit{Id="M",PowerKw=9,Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",CableMm2=10};load.Cable.ResistanceOhmKm=1.83;load.Cable.ReactanceOhmKm=.08;load.Cable.AmpacityA=50;d.Circuits.Add(load);e.Circuits.Add(new Circuit{Id="OTHER",PowerKw=2,Voltage=230});Near(Engineering.Analyze(p).TotalKw,11,"roots initial");var ab=DiagramEditing.Connect(p,a,b);var bd=DiagramEditing.Connect(p,b,d);Check(ab.PowerKw==0&&bd.PowerKw==0&&ab.ChildBoardId=="B"&&bd.ChildBoardId=="D","own zero-load feeders");Check(ab.Phases==PhaseMode.Trifasico&&ab.PhaseLabel=="ABC"&&ab.Voltage==400,"threephase feeder conditions");Check(ab.Id!=bd.Id&&ab.Id!="M","global IDs");var study=Engineering.Analyze(p);Near(study.For(ab).DemandKw,9,"two downstream levels propagate");Near(study.For(bd).DemandKw,9,"one downstream level");Near(study.TotalKw,11,"no double count");Reject(()=>DiagramEditing.Connect(p,a,d),"duplicate parent refused");Check(a.Circuits.Count==1&&d.Circuits.Count==1,"failed connect leaves graph");Reject(()=>DiagramEditing.Connect(p,d,a),"cycle refused");Check(d.Circuits.Count==1,"cycle rolled back");Reject(()=>DiagramEditing.Connect(p,a,a),"selfloop refused");Reject(()=>DiagramEditing.Connect(p,new Board(),b),"foreign origin");Reject(()=>DiagramEditing.Connect(p,a,new Board()),"foreign target");e.Voltage=380;Reject(()=>DiagramEditing.Connect(p,a,e),"voltage mismatch");e.Voltage=400;Check(a.Circuits.Count==1,"voltage failure no mutation");Reject(()=>DiagramEditing.Reconnect(p,d,load,e),"no silent conversion of terminal load");Check(load.PowerKw==9&&load.ChildBoardId=="","terminal preserved");ab.CableMm2=16;ab.Cable.ResistanceOhmKm=1.15;ab.Cable.ReactanceOhmKm=.08;ab.Cable.AmpacityA=63;ab.BreakerA=32;bd.CableMm2=10;bd.Cable.ResistanceOhmKm=1.83;bd.Cable.ReactanceOhmKm=.08;bd.Cable.AmpacityA=50;ab.LengthM=50;bd.LengthM=30;var old=Engineering.Analyze(p);double downstreamDrop=old.For(load).AccumulatedDropPercent;Check(downstreamDrop>old.For(bd).AccumulatedDropPercent&&old.For(bd).AccumulatedDropPercent>old.For(ab).AccumulatedDropPercent,"drop recalculated through three levels");DiagramEditing.Move(p,a,ab,420,180);Near(ab.DiagramX,420,"position x");Near(ab.DiagramY,180,"position y");Reject(()=>DiagramEditing.Move(p,a,ab,44,180),"invalid position");Reject(()=>DiagramEditing.Move(p,a,ab,double.NaN,180),"nonfinite position");Near(ab.DiagramX,420,"failed move atomic");Near(Engineering.Analyze(p).For(load).AccumulatedDropPercent,downstreamDrop,"geometry electrically invariant");Reject(()=>DiagramEditing.Reconnect(p,a,ab,d),"reconnect duplicate parent");Check(ab.ChildBoardId=="B","failed reconnect restores target");Reject(()=>DiagramEditing.Reconnect(p,b,bd,a),"reconnect cycle");Check(bd.ChildBoardId=="D","cycle reconnect restored");DiagramEditing.Reconnect(p,a,ab,e);Near(Engineering.Analyze(p).For(ab).DemandKw,2,"reconnect follows new subtree");Near(Engineering.Analyze(p).For(bd).DemandKw,9,"old subtree remains root");Near(Engineering.Analyze(p).TotalKw,11,"reconnect conserves loads");Check(ab.BreakerA==32&&ab.CableMm2==16&&ab.DiagramX==420,"reconnect hardware geometry preserved");DiagramEditing.Reconnect(p,a,ab,b);Near(Engineering.Analyze(p).For(load).AccumulatedDropPercent,downstreamDrop,"restore exact electrical path");string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-unifilar");Directory.CreateDirectory(folder);p.Save(Path.Combine(folder,"rede.circuito"));using(var writer=new StreamWriter(Path.Combine(folder,"resultados.csv"))){writer.WriteLine("Id;DemandKw;CurrentA;DropPercent");foreach(var row in Engineering.Analyze(p).Circuits)writer.WriteLine(row.Circuit.Id+";"+row.DemandKw.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+";"+row.CurrentA.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+";"+row.AccumulatedDropPercent.ToString("R",System.Globalization.CultureInfo.InvariantCulture));}DiagramSvg.Save(p,a,Path.Combine(folder,"raiz.svg"));DiagramSvg.Save(p,b,Path.Combine(folder,"distribuicao.svg"));var reopened=Project.Load(Path.Combine(folder,"rede.circuito"));Near(Engineering.Analyze(reopened).For(reopened.Boards[2].Circuits[0]).AccumulatedDropPercent,downstreamDrop,"persist topology and studies");Check(reopened.Boards[0].Circuits[0].DiagramX==420,"persist placement");Check(File.ReadAllText(Path.Combine(folder,"raiz.svg")).Contains("→ quadro B"),"export actual target");File.WriteAllText(Path.Combine(folder,"memoria.txt"),EngineeringReport.Memory(p,Engineering.Analyze(p)));using(var form=new DiagramConnectionsForm(p,a,ab)){Check(!form.Changed,"opening editor no mutation");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var image=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(image))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);image.Save(Path.Combine(folder,"conexoes.png"));}form.Hide();}}if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){using(var view=new Form{Size=new Size(1050,650),StartPosition=FormStartPosition.Manual,Location=new Point(10,10)}){var diagram=new Diagram{Project=p,Board=a,Study=Engineering.Analyze(p),Selected=ab,Dock=DockStyle.Fill};view.Controls.Add(diagram);view.Show();Application.DoEvents();view.Refresh();view.Update();using(var bitmap=new Bitmap(view.ClientSize.Width,view.ClientSize.Height)){using(var g=Graphics.FromImage(bitmap))g.CopyFromScreen(view.PointToScreen(Point.Empty),Point.Empty,view.ClientSize);bitmap.Save(Path.Combine(folder,"unifilar.png"));}view.Hide();}}ab.PowerKw=999;DiagramEditing.Disconnect(p,a,ab);Check(!a.Circuits.Contains(ab)&&p.Boards.Contains(b)&&b.Circuits.Contains(bd),"disconnect removes feeder not subtree");Near(Engineering.Analyze(p).TotalKw,11,"disconnect no phantom feeder load");Reject(()=>DiagramEditing.Disconnect(p,d,load),"terminal not disconnectable");Reject(()=>DiagramEditing.Disconnect(p,a,ab),"stale feeder rejected");ProjectEditing.RemoveCircuit(p,d,load);Near(Engineering.Analyze(p).TotalKw,2,"delete symbol recalculates downstream and root");var inserted=ProjectEditing.AddCircuit(p,d);Near(Engineering.Analyze(p).For(bd).DemandKw,1,"insert symbol recomputes upstream");Check(inserted.Id!="OTHER","insert unique id");Console.WriteLine("PASS: "+n+" diagram editing assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
